 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static int count;static MainWindow main;static ClientSession session;static string root;
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 static void Pump(){var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);}
 static void Until(Func<bool> ready){var end=DateTime.UtcNow.AddSeconds(15);while(!ready()&&DateTime.UtcNow<end){Pump();Thread.Sleep(10);}Check(ready(),"asynchronous view ready");}
 static T[] All<T>(DependencyObject obj)where T:DependencyObject{var list=new List<T>();for(int i=0;i<VisualTreeHelper.GetChildrenCount(obj);i++){var c=VisualTreeHelper.GetChild(obj,i);if(c is T)list.Add((T)c);list.AddRange(All<T>(c));}return list.ToArray();}
 static void Page(string name){typeof(MainWindow).GetMethod("Page",F).Invoke(main,new object[]{name});Pump();main.UpdateLayout();}
 static void Click(DependencyObject window,string caption){All<Button>(window).First(b=>Convert.ToString(b.Content)==caption).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
 static void Save(Window window,string name){window.UpdateLayout();var bitmap=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(root,name+".png")))encoder.Save(stream);}
 static void Wait(System.Threading.Tasks.Task task){Until(()=>task.IsCompleted);task.GetAwaiter().GetResult();}
 static void Modal(string method,Action<Window> inspect,object[] args=null){Exception error=null;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(30)};timer.Tick+=(s,e)=>{var dialog=Application.Current.Windows.Cast<Window>().FirstOrDefault(w=>w!=main);if(dialog==null)return;timer.Stop();try{Pump();dialog.UpdateLayout();inspect(dialog);dialog.Close();}catch(Exception ex){error=ex;dialog.Close();}};timer.Start();var task=typeof(MainWindow).GetMethod(method,F).Invoke(main,args) as System.Threading.Tasks.Task;if(task!=null)Wait(task);timer.Stop();if(error!=null)throw error;Check(typeof(MainWindow).GetField("modalVeil",F).GetValue(main)==null,"modal backdrop completely removed");}
